import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1206, own='cte_129.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("878.d.1.A",3,"An Automotive Technology II student writes a detailed summary of a transmission leak diagnosis for the service file, covering symptoms, tests and the repair. This is:","effective written communication throughout the course",["avoiding documentation","a casual text","an unrelated essay"],"Detailed, accurate writing.")
H("878.d.1.A",4,"Which written entry best serves the next technician who works on the vehicle?","one that states the symptom, tests performed, findings and parts replaced",["'Car is weird'","'Looks okay'","'Done'"],"Complete records.")
H("878.d.1.B",3,"A service writer lists 1.8 hours of diagnosis, a $92 sensor and a $14 gasket on the repair order. She is:","estimating the cost of parts and labor operations on a repair order",["hiding costs","guessing","avoiding quotes"],"Estimating.")
H("878.d.1.B",4,"A job needs $140 in parts and 2.5 hours at $96 per hour. The estimate is:","$380",["$236","$335","$480"],"140 + 240 = 380.")
H("878.d.1.C",3,"A technician converts a measured 0.125 inch of rotor wear to a fraction and compares it to the specification. She is:","using mathematical skills such as fractions and decimals",["guessing","ignoring numbers","avoiding math"],"Decimal and fraction fluency.")
H("878.d.1.C",4,"A tire's tread measures 6/32 inch and wears 1/32 inch every 5,000 miles. How many miles until it reaches 2/32 inch?","20,000 miles",["5,000 miles","10,000 miles","30,000 miles"],"4 × 5,000 = 20,000.")
H("878.d.1.D",3,"A student looks up the vehicle's service history and a related technical bulletin before starting an electrical diagnosis. She is:","researching applicable vehicle and service information, including service history",["ignoring data","guessing","skipping research"],"Research first.")
H("878.d.1.D",4,"Reviewing a vehicle's previous repair history can help a technician:","avoid repeating a failed repair and spot patterns",["raise the price","skip testing","ignore the complaint"],"History reveals patterns.")
H("878.d.2.A",3,"A student explains how the engine, transmission, driveshaft, differential and axles work together to move a car, and tests each in turn. She is:","diagnosing the major components of a powered vehicle",["painting","guessing","ignoring parts"],"Diagnose systems.")
H("878.d.2.A",4,"A clunk heard only when shifting from reverse to drive most likely points to:","worn driveline or mount components",["a loose antenna","low washer fluid","a dim bulb"],"Torque transfer.")
H("878.d.2.B",3,"A technician rocks the front wheels, then shakes a driveshaft joint to find play in the chassis and driveline. She is:","diagnosing chassis and driveline components",["washing the car","painting","guessing"],"Chassis and driveline.")
H("878.d.2.B",4,"A vibration that increases with road speed and is felt in the floor often traces to:","an out-of-balance driveshaft or tire",["a dim lamp","low washer fluid","a worn key fob"],"Speed-related vibration.")
H("878.d.2.C",3,"A technician reads a wiring schematic, a torque chart and a fluid diagram before starting a repair. She is:","locating, reading and interpreting service documents",["ignoring documents","guessing","using memory only"],"Read the documents.")
H("878.d.2.C",4,"On a wiring schematic, a line with an arrow-like triangle and a bar commonly represents a:","diode",["fuse","switch","motor"],"Symbols matter.")
H("878.d.2.D",3,"A technician checks the recommended service intervals in the maintenance schedule for a 60,000-mile service. She is:","locating the manufacturer's recommended preventative maintenance schedule",["guessing","ignoring intervals","skipping service"],"Follow the schedule.")
H("878.d.2.D",4,"Following the manufacturer's schedule helps protect the vehicle's:","warranty and long-term reliability",["paint color","radio","seat covers"],"Schedule keeps warranty.")
H("878.d.2.E",3,"A technician follows a multi-point inspection form covering fluids, belts, hoses, tires, lights and brakes. She is performing:","a preventative maintenance inspection",["a body repair","a sale","a paint job"],"PM inspection.")
H("878.d.2.E",4,"On an inspection form, a worn belt should be marked as:","needing replacement, with a note for the customer",["fine","ignore","optional paint"],"Document needs.")
H("878.d.2.F",3,"A technician uses a thread chaser, a helical insert and an extractor to repair a stripped drain-plug hole and a snapped stud. She is performing:","common fastener and thread repair",["painting","guessing","avoiding repair"],"Thread repair.")
H("878.d.2.F",4,"A bolt that snaps flush with the surface can often be removed with:","a screw extractor after drilling a pilot hole",["a hammer only","more torque","paint remover"],"Extraction process.")
H("878.d.2.G",3,"A technician uses a micrometer to measure a brake rotor's thickness and a dial indicator for runout, then compares the numbers to published specifications. She is:","performing precision measurements and using published specifications to diagnose wear",["guessing","ignoring specs","painting"],"Measure to spec.")
H("878.d.2.G",4,"If a rotor's thickness variation is greater than the specification, the technician should:","resurface (within limits) or replace the rotor",["ignore it","paint it","add grease"],"Out of spec.")
H("878.d.2.H",3,"A technician follows a step-by-step plan: verify the complaint, check the basics, test, isolate the fault and verify the repair. She is employing:","critical-thinking and structured problem-solving skills",["random guessing","avoiding thought","luck"],"Structured diagnosis.")
H("878.d.2.H",4,"After repairing a fault, the final problem-solving step is to:","verify the repair and confirm the complaint is gone",["ignore the car","paint the engine","send the bill only"],"Verify fix.")
H("878.d.3.A",3,"A student inspects an air hammer's hose and connection, wears hearing and eye protection, and keeps others clear before use. She is demonstrating:","the proper and safe use of hand and power tools and equipment",["unsafe habits","ignoring rules","careless setup"],"Safe tool use.")
H("878.d.3.A",4,"Compressed air should never be used to:","blow dust off clothing or skin",["blow debris off a bench","inflate a tire","operate an air tool"],"Injury risk.")
H("878.d.3.B",3,"A student recycles used antifreeze, brake fluid and oil filters in marked containers and explains why. She is discussing and demonstrating:","proper handling and disposal of environmentally hazardous materials",["dumping","ignoring rules","careless disposal"],"Hazmat.")
H("878.d.3.B",4,"Used coolant is hazardous because it:","is toxic to animals and people",["is harmless","is edible","is clean water"],"Antifreeze is poisonous.")
H("878.d.3.C",3,"A student connects a lab scope to a sensor wire and a scan tool to the data port to compare signals. She is demonstrating:","the proper use of diagnostic tools and equipment",["guessing","using a hammer","painting"],"Diagnostic tools.")
H("878.d.3.C",4,"An oscilloscope shows a technician:","a voltage signal's pattern over time",["tire tread","oil color","fuel octane"],"Waveform display.")
H("878.d.3.D",3,"A student finds the torque sequence, fluid capacity and a wiring schematic in the service information system for a specific vehicle. She is:","locating, reading and interpreting service repair information",["guessing","ignoring data","using memory only"],"Service information.")
H("878.d.3.D",4,"A service information system is more reliable than a generic internet forum because it:","contains manufacturer-approved procedures and specifications",["has more pictures","has no errors ever","is shorter"],"Authoritative source.")
H("878.d.4.A",3,"A student inspects a power steering high-pressure hose for chafing and replaces a leaking fitting. She is:","inspecting and replacing power steering hoses and fittings",["painting","ignoring leaks","guessing"],"PS hose service.")
H("878.d.4.A",4,"A power steering fluid leak at a hose crimp most likely requires:","replacing the hose assembly",["adding tape","ignoring it","adding more fluid only"],"Crimped hose.")
H("878.d.4.B",3,"A student removes a hub, washes the bearing, checks the race, repacks it with fresh grease and installs a new seal. She is:","removing, cleaning, inspecting, repacking and installing wheel bearings and replacing seals",["painting","guessing","avoiding service"],"Bearing service.")
H("878.d.4.B",4,"After installing a repacked bearing, the nut should be tightened according to:","the manufacturer's procedure and specification",["whatever feels loose","a random torque","no specification"],"Follow spec.")
H("878.d.4.C",3,"A student presses a damaged bearing race from a hub and installs a new race squarely with a driver. She is:","replacing a wheel bearing and race",["painting","guessing","avoiding repair"],"Race replacement.")
H("878.d.4.C",4,"A new bearing race should be installed:","squarely and fully seated with the proper driver",["with a hammer only","crooked","loosely"],"Seat evenly.")
H("878.d.4.D",3,"Before working near an airbag module, a technician follows the manufacturer's steps to disconnect the battery and wait for the stored energy to drain. She is:","disabling the supplemental restraint system",["washing the car","tuning a radio","painting"],"Disable SRS.")
H("878.d.4.D",4,"After re-enabling an SRS system, the technician should:","verify that the warning light operates and then goes out",["ignore the dash","leave it disabled","disconnect the battery"],"Verify SRS.")
H("878.d.4.E",3,"A student compresses a strut spring with a rated spring compressor, removes the strut and inspects the strut mount and bearing. She is:","inspecting, removing and replacing shock absorbers and struts and inspecting mounts",["painting","guessing","ignoring parts"],"Strut service.")
H("878.d.4.E",4,"A coil spring should be handled with a spring compressor because it:","stores a large amount of energy that can cause injury",["is fragile","is magnetic","is hot"],"Stored energy.")
H("878.d.4.F",3,"A student removes the tire from a wheel with a pressure sensor, checks the sensor and valve stem, and remounts it without damaging the sensor. She is:","dismounting, inspecting and remounting a tire on a wheel equipped with a pressure sensor",["painting","guessing","avoiding tire work"],"TPMS wheel care.")
H("878.d.4.F",4,"When changing a tire on a wheel with a TPMS sensor, the technician should rotate the bead breaker away from the valve to:","avoid damaging the sensor",["save time","improve grip","shine the wheel"],"Protect the sensor.")
H("878.d.4.G",3,"A student inspects a rear suspension's lateral links, trailing arms, leaf springs and bushings for wear and bent parts. She is:","inspecting the rear suspension system",["ignoring parts","painting","guessing"],"Rear suspension.")
H("878.d.4.G",4,"A cracked rear leaf spring or a worn bushing may cause:","poor handling and uneven tire wear",["better steering","a quieter radio","a cooler engine"],"Suspension wear.")
H("878.d.4.H",3,"A student inspects tires for cupping and feathering, checks the size and the load and speed ratings against the placard. She is:","inspecting tire condition and wear patterns and checking for the correct size and application",["ignoring tires","painting","guessing"],"Tire inspection.")
H("878.d.4.H",4,"Wear on both outer edges of a tire most often indicates:","chronic under-inflation",["over-inflation","good alignment","a new tire"],"Edge wear means low pressure.")
H("878.d.4.I",3,"A student measures the distance from the wheel center to the fender lip at each corner before an alignment. She is:","performing a pre-alignment inspection and measuring vehicle ride height",["painting","guessing","ignoring heights"],"Ride height.")
H("878.d.4.I",4,"A pre-alignment inspection is important because an alignment cannot be accurate if the vehicle has:","worn or damaged steering and suspension parts",["clean tires","fresh paint","a new radio"],"Fix worn parts first.")
H("878.d.4.J",3,"A student submerges a tire and wheel assembly in water and watches for bubbles at the bead and valve. She is:","inspecting a tire and wheel assembly for air loss",["painting","ignoring leaks","guessing"],"Leak test.")
H("878.d.4.J",4,"Bubbles forming at the rim edge of a tire usually indicate a leak at the:","bead seal",["valve cap color","tread","sidewall logo"],"Bead leak.")
H("878.d.4.K",3,"A student compares a direct TPMS, which has a sensor in each wheel, with an indirect system that uses wheel-speed data, and checks the dash indicator. She is:","identifying and testing indirect and direct TPMSs and the instrument panel indicator",["ignoring TPMS","painting","guessing"],"TPMS types.")
H("878.d.4.K",4,"An indirect TPMS estimates low pressure by:","comparing the rotational speed of each wheel",["reading the tire tread","measuring tire temperature","reading a barometer"],"Smaller tires spin faster.")
H("878.d.4.L",3,"A student reviews the steps to remove and replace a wheel sensor, including relearning its position with a scan tool. She is:","demonstrating knowledge of the steps to remove and replace TPMS sensors",["painting","guessing","ignoring sensors"],"TPMS replacement.")
H("878.d.4.L",4,"After a TPMS sensor is replaced, the technician must often:","perform a relearn procedure so the system recognizes the sensor",["leave the light on","paint the wheel","skip the step"],"Relearn.")
H("878.d.4.M",3,"A student removes a front-wheel-drive hub assembly and CV axle, inspects the bearing and seals and reinstalls them. She is:","inspecting, removing and replacing FWD bearings, hubs and seals",["painting","guessing","ignoring wear"],"FWD hub service.")
H("878.d.4.M",4,"A front wheel bearing that growls and gets louder when turning left probably has:","wear in the bearing on the loaded (right) side",["a flat tire","a dead battery","a loose wiper"],"Load transfer.")
H("878.d.5.A",3,"A student explains that a chafed power wire touching the frame will blow a fuse, while a corroded connector adds unwanted resistance. She is demonstrating knowledge of:","the causes and effects of shorts, opens and resistance problems in circuits",["tire wear","brake wear","fuel flow"],"Circuit faults.")
H("878.d.5.A",4,"High resistance in a headlight connection will most likely cause:","dim light and heat at the connector",["brighter light","no effect","a cooler wire"],"Voltage drop.")
H("878.d.5.B",3,"A technician connects an ammeter in series after the car sleeps for 30 minutes and finds a 200 milliamp draw. She is:","measuring key-off battery drain (parasitic draw)",["testing the starter","testing tires","testing oil"],"Parasitic draw test.")
H("878.d.5.B",4,"A battery that is dead each morning, with a normal charging system, suggests:","an excessive parasitic draw",["a perfect battery","an overcharge","a bad tire"],"Draw drains battery.")
H("878.d.5.C",3,"A technician heats a spliced wire, flows solder into it and covers it with heat-shrink tubing. She is:","performing a solder repair of electrical wiring",["gluing a wire","taping only","painting"],"Solder splice.")
H("878.d.5.C",4,"A good solder joint should look:","smooth and shiny, not dull or lumpy",["dull and grainy","burned black","cracked"],"Visual check.")
H("878.d.5.D",3,"A technician crimps a new terminal onto a wire and snaps it into a weather-pack connector. She is:","replacing an electrical connector and terminal end",["painting","guessing","avoiding repair"],"Terminal replacement.")
H("878.d.5.D",4,"A sealed connector in a wheel-well harness is used to:","keep water and dirt out of the terminals",["add voltage","let in air","look neat"],"Seal prevents corrosion.")
H("878.d.5.E",3,"Before disconnecting the battery, a technician plugs a memory saver into the diagnostic port so the radio presets and the settings are kept. She is:","maintaining or restoring electronic memory functions",["erasing settings","guessing","ignoring memory"],"Memory saver.")
H("878.d.5.E",4,"After a battery replacement, the technician may need to reset the:","radio, clock and window auto-up learning",["tire pressure only","oil level","brake fluid"],"Relearn settings.")
H("878.d.5.F",3,"A technician selects a 10-amp slow charge for a deeply discharged battery and monitors the temperature. She is:","performing a slow battery charge according to the manufacturer's recommendations",["painting","guessing","overcharging"],"Slow charging.")
H("878.d.5.F",4,"A fast charge can damage a battery if it:","is used too long or lets the battery overheat",["is cooled","is monitored","is short"],"Heat damage.")
H("878.d.5.G",3,"A technician locates the body control module, the immobilizer antenna and the radio head unit on a vehicle diagram. She is:","identifying electronic modules, security systems, radios and other accessories",["ignoring modules","painting","guessing"],"Find modules.")
H("878.d.5.G",4,"An immobilizer system prevents a car from starting when it:","does not recognize the key's transponder code",["has low fuel","has a loose gas cap","is cold"],"Security feature.")
H("878.d.5.H",3,"A technician measures the voltage lost across the starter cable while the engine cranks, along with the current draw. She is performing:","a starter current draw test and a starter circuit voltage drop test",["a fuel test","a tire test","an oil test"],"Starter tests.")
H("878.d.5.H",4,"A voltage drop of more than about 0.5 volts across a starter cable means the cable has:","excess resistance, often from a bad connection",["a perfect connection","low draw","too little current"],"Excess resistance.")
H("878.d.5.I",3,"A technician disconnects the battery, removes the starter's mounting bolts and wires, installs a new starter and torques the bolts. She is:","removing and installing a starter in a vehicle",["washing the car","painting","tuning the radio"],"Starter replacement.")
H("878.d.5.I",4,"Before removing a starter, the technician should first:","disconnect the negative battery cable",["start the engine","jack the front wheel","remove the oil cap"],"Disconnect power.")
H("878.d.5.J",3,"A technician tests the ignition switch, neutral safety switch, relay and wires of the circuit that tells the starter to crank. She is:","inspecting and testing the switches, connectors and wires of the starter control circuit",["painting","guessing","ignoring wires"],"Control circuit.")
H("878.d.5.J",4,"If the starter does not click when the key is turned, but the battery is strong, one suspect is:","the starter relay or ignition switch",["a flat tire","the washer pump","the wiper blade"],"Control circuit fault.")
H("878.d.5.K",3,"A technician revs the engine to 2,500 rpm and measures the alternator's output current and voltage, and compares them with spec. She is performing:","a charging system output test",["a fuel test","a tire test","a brake test"],"Output test.")
H("878.d.5.K",4,"An alternator that produces 12.0 volts with the engine at 2,500 rpm is:","not charging properly",["perfect","overcharging","fully charged"],"Needs 13.5–14.8 V.")
H("878.d.5.L",3,"A technician removes the drive belt, unplugs the alternator, removes the mounting bolts, inspects the pulley and reinstalls it. She is:","removing, inspecting and re-installing an alternator",["painting","guessing","avoiding repair"],"Alternator replacement.")
H("878.d.5.L",4,"After installing an alternator, the belt tension and alignment should be:","checked to prevent slipping and premature wear",["ignored","left loose","painted"],"Check tension.")
H("878.d.5.M",3,"A student learns that hybrid high-voltage cables are colored orange and that gloves rated for the voltage must be worn. She is identifying:","system voltage and safety precautions associated with high-voltage systems",["tire pressure","oil capacity","wiper speed"],"Orange means high voltage.")
H("878.d.5.M",4,"Before working on a hybrid's high-voltage system, a technician should:","disable the system using the manufacturer's service disconnect procedure",["touch the cables to test","remove the radio","start the engine"],"Disconnect HV.")
H("878.d.5.N",3,"A technician disconnects the battery, waits for the specified time and confirms the airbag light behaves normally after reconnecting. She is:","disabling and enabling the airbag system and verifying the indicator",["ignoring airbags","painting","guessing"],"Airbag service.")
H("878.d.5.N",4,"If the airbag light stays on after a repair, the technician should:","scan for stored SRS codes and correct the fault",["ignore it","cover it","disconnect the battery"],"Diagnose SRS.")
H("878.d.5.O",3,"A technician removes the screws, releases the clips, unplugs the switch harness and lifts off a door panel. She is:","removing and reinstalling a door panel",["painting the door","tuning a radio","washing the car"],"Door panel.")
H("878.d.5.O",4,"Plastic panel clips are best released using:","a trim removal tool",["a screwdriver and force","pliers","a hammer"],"Avoid breaking clips.")
H("878.d.5.P",3,"A student explains that a key fob sends a coded radio signal to unlock doors or start the engine from a distance. She is describing:","the operation of keyless entry and remote-start systems",["a paint system","a tire system","a fuel system"],"Keyless entry.")
H("878.d.5.P",4,"If a key fob stops working suddenly, the first thing to check is:","the fob battery",["the tire pressure","the oil","the wipers"],"Weak fob battery.")
H("878.d.6.A",3,"A technician drives the car on a quiet road, noting pedal feel, pulling and noises while braking firmly in a safe area. She is:","describing a procedure for performing a road test to check brake system operation",["racing","guessing","ignoring"],"Road test.")
H("878.d.6.A",4,"During a brake road test, a pull to the right when braking suggests:","uneven braking force from a sticking caliper or hose",["a perfect system","a clean windshield","a dead battery"],"Pull means uneven.")
H("878.d.6.B",3,"A technician measures how high the pedal sits, how far it travels and how much free play it has, then compares the numbers to spec. She is:","measuring brake pedal height, reserve distance, travel and free play",["painting","guessing","ignoring spec"],"Pedal measurements.")
H("878.d.6.B",4,"A pedal that goes nearly to the floor before the brakes engage may indicate:","a leak or air in the hydraulic system",["a perfect system","a clean filter","a new tire"],"Low pedal.")
H("878.d.6.C",3,"A student traces the red BRAKE lamp circuit to the parking brake switch, the fluid level sensor and the pressure differential switch. She is:","identifying components of the brake warning light system",["ignoring lights","painting","guessing"],"Warning light.")
H("878.d.6.C",4,"The brake warning light may glow when the:","brake fluid level is low or the parking brake is applied",["radio is on","tank is full","windows are open"],"Common triggers.")
H("878.d.6.D",3,"A technician pumps and holds the pedal while a helper opens the bleeder, watching for clear fluid with no bubbles. She is:","bleeding and flushing the brake system",["washing the car","painting","tuning the radio"],"Brake bleed.")
H("878.d.6.D",4,"Brake fluid should be flushed periodically because it:","absorbs moisture over time, lowering its boiling point",["gets thicker","gets sweeter","burns off"],"Hygroscopic.")
H("878.d.6.E",3,"A technician presses the pedal while a partner checks that the center and both rear stop lamps light, then checks the switch. She is:","identifying and checking the operation of the brake stop light system",["ignoring lights","painting","guessing"],"Stop lamp check.")
H("878.d.6.E",4,"If none of the stop lights work, a good first check is the:","brake light switch and fuse",["tire pressure","oil level","wiper blades"],"Check switch and fuse.")
H("878.d.6.F",3,"A student identifies the wheel-speed sensors, the yaw sensor and the hydraulic control unit used by traction and stability control. She is:","identifying traction control and vehicle stability control system components",["painting","ignoring sensors","guessing"],"Stability control parts.")
H("878.d.6.F",4,"Stability control helps a driver by:","applying individual brakes to correct a skid",["adding speed","shutting off the engine","increasing noise"],"Corrects skids.")
H("878.d.7.A",3,"A technician learns that the emissions monitors must complete a drive cycle before a car can pass a state inspection. She is describing:","the importance of operating all OBD II monitors for repair verification",["painting","guessing","ignoring monitors"],"Monitors verify repairs.")
H("878.d.7.A",4,"An OBD II 'not ready' status after clearing codes means:","the monitors have not finished running",["the car is broken","the battery is dead","the tires are low"],"Not ready is normal initially.")
H("878.d.7.B",3,"A technician disables one cylinder at a time and watches the change in rpm to find a weak cylinder. She is performing:","a cylinder power balance test",["a tire test","a brake test","an oil test"],"Power balance.")
H("878.d.7.B",4,"If disabling one cylinder causes no change in rpm, that cylinder is:","not contributing power",["perfect","overworking","too cool"],"No change means weak.")
H("878.d.7.C",3,"A technician cranks the engine and records the compression on each cylinder with a gauge and compares to the specification. She is performing:","cylinder cranking and running compression tests",["a fuel test","a tire test","a battery test"],"Compression test.")
H("878.d.7.C",4,"Two adjacent cylinders with very low compression often indicate:","a blown head gasket between them",["a perfect engine","low tire pressure","a dead battery"],"Adjacent cylinders.")
H("878.d.7.D",3,"A technician pressurizes a cylinder with compressed air and listens for leaks at the intake, exhaust and radiator. She is performing:","a cylinder leakage test",["a tire test","an oil test","a fuel test"],"Leakage test.")
H("878.d.7.D",4,"Air heard hissing from the tailpipe during a leakage test points to a:","leaking exhaust valve",["bad plug","bad tire","dead battery"],"Exhaust valve.")
H("878.d.7.E",3,"A technician watches a scan tool's coolant temperature reading as the engine warms and compares it to the thermostat spec. She is:","verifying the engine operating temperature",["measuring oil","measuring fuel","measuring tires"],"Check temperature.")
H("878.d.7.E",4,"A coolant temperature sensor that reads far below actual temperature can cause:","a rich mixture and poor fuel economy",["a lean mixture","better mileage","a cooler engine"],"Sensor affects fueling.")
H("878.d.7.F",3,"A technician replaces spark plugs on a four-cylinder engine, checks the gap and applies the correct torque. She is:","removing and replacing spark plugs and inspecting secondary ignition components",["painting","guessing","avoiding service"],"Spark plug service.")
H("878.d.7.F",4,"A spark plug with white, blistered insulator may indicate:","overheating or a lean condition",["a rich mixture","normal wear","cold running"],"Read the plug.")
H("878.d.7.G",3,"A technician uses a scan tool to read stored codes and freeze-frame data and records them on the repair order. She is:","retrieving and recording diagnostic trouble codes and OBD II monitor status",["ignoring data","painting","guessing"],"Record data.")
H("878.d.7.G",4,"Freeze-frame data on a scan tool shows:","engine conditions at the moment the code was set",["tire wear","oil capacity","paint code"],"Snapshot.")
H("878.d.8.A",3,"A technician cleans the mating surfaces, applies the specified sealer and installs a valve cover with a new gasket. She is:","installing engine covers using gaskets, seals and sealers as required",["painting","guessing","avoiding service"],"Cover installation.")
H("878.d.8.A",4,"Too much RTV sealer on a valve cover can:","squeeze inside and clog oil passages",["improve the seal","reduce leaks","cool the engine"],"Excess sealer.")
H("878.d.8.B",3,"A technician aligns the cam and crank timing marks, installs the new timing belt and rotates the engine by hand twice to confirm the marks line up. She is:","replacing a timing belt and verifying correct camshaft timing",["painting","guessing","avoiding service"],"Timing belt.")
H("878.d.8.B",4,"If a timing belt breaks on an interference engine, the result is likely:","bent valves and expensive damage",["no damage","better power","quieter running"],"Interference engines.")
H("878.d.8.C",3,"A technician pressurizes the radiator and adds UV dye to locate a seep in the cooling system. She is performing:","cooling system pressure and dye tests to identify leaks",["painting","guessing","avoiding tests"],"Cooling system leak test.")
H("878.d.8.C",4,"A cooling system that loses pressure but shows no external leak may have:","a leaking head gasket or heater core",["a bad tire","a dead battery","a loose antenna"],"Internal leak.")
H("878.d.8.D",3,"A technician drains the coolant, removes the thermostat housing and installs a new thermostat with the spring toward the engine. She is:","removing, inspecting and replacing the thermostat and gasket or seal",["painting","guessing","avoiding service"],"Thermostat replacement.")
H("878.d.8.D",4,"A thermostat that is stuck closed will make the engine:","overheat quickly",["run cold","use less fuel","run quietly"],"Stuck closed overheats.")
H("878.d.9.A",3,"A technician opens the glove box, releases the filter door and replaces a gray, leaf-filled cabin air filter. She is:","identifying, locating and replacing the cabin air filter",["painting","guessing","avoiding service"],"Cabin filter.")
H("878.d.9.A",4,"A cabin air filter is installed with the airflow arrow:","pointing in the direction of airflow",["against the flow","at random","hidden"],"Direction matters.")
H("878.d.9.B",3,"A technician rinses road debris from the condenser fins and checks for bent fins that block air. She is:","inspecting the A/C condenser for airflow restrictions",["painting","guessing","ignoring debris"],"Condenser check.")
